from common import *
m=load_manifest()
def ts(s):
 ms=round(s*1000);return f'{ms//60000:02}:{ms//1000%60:02}.{ms%1000:03}'
lines=['# OPPO Bắc Ninh 20/10 — bản rút gọn','',f"Timeline: **{ts(m['totalFrames']/60)}**, 2560×1440, 60 FPS; H.264 CRF 17, AAC stereo 48 kHz 320 kb/s.",'','52 ảnh thật được sắp xếp theo tên file Unicode; bỏ qua SVG mẫu. Mỗi scene ảnh đúng 360 frame (6 giây), crossfade 27 frame (0,45 giây), có 5,1 giây không chồng ảnh hai bên. Không kéo dài theo nhạc. Zoom 94–99% kiểu contain giữ toàn bộ nội dung ảnh.','', 'Cấu trúc: Intro + tiêu đề → 13 ảnh → 4 lời chúc → 13 ảnh → 4 lời chúc → 13 ảnh → 4 lời chúc → 13 ảnh → 4 lời chúc → lời chúc chung → Outro. Các bảng dẫn nhóm chỉ 2,5 giây, có chồng chuyển cảnh.','','## 16 lời chúc đã biên tập','','Mốc nguồn tính bằng giây. “Đoạn xuất” gồm đệm hình và chuyển cảnh; tất cả dưới 18 giây. Các clip gốc ngắn giữ nhịp tự nhiên. Tăng tốc dùng atempo giữ cao độ.','','| # | Tên / chức vụ từ file | Mốc bắt đầu trong phim | Đoạn giữ trong nguồn | Tốc độ | Lời nói | Đoạn xuất |','|---|---|---|---|---|---|---|']
for s in m['scenes']:
 if s['kind']=='wish':lines.append(f"| {s['number']} | {s['name']} / {s['role']} | {ts(s['startFrame']/60)} | {s['trimStartSeconds']:.2f}–{s['trimEndSeconds']:.2f}s | {s['speed']:.2f}× | {s['keptSeconds']:.2f}s | {s['durationInFrames']/60:.2f}s |")
lines+=['','Tổng lời nói giữ lại: '+f"{sum(s['keptSeconds'] for s in m['wishes']):.2f} giây.",'','## Phần lược bỏ','']
for s in m['wishes']:lines.append(f"- **{s['number']:02}. {s['name']}**: {s['editNote']} Phần bỏ: 0–{s['trimStartSeconds']:.2f}s và {s['trimEndSeconds']:.2f}–{s['sourceSeconds']:.2f}s.")
lines+=['','Điểm cắt dựa trên mốc từ/câu nhận dạng tiếng Việt, có đệm trước và sau câu. Văn bản ASR có thể sai chính tả; không dùng ASR để viết tên hay chức vụ lên phim. Chi tiết và SHA nguồn được lưu trong `src/data/speech-edits.json`; khi nguồn đổi, quy trình dừng để kiểm tra lại.','','## Hình ảnh và âm thanh','','- Video 2: pixels quay ngang sai hướng, không có metadata xoay; chỉ thêm 90° ngược chiều kim đồng hồ.','- Video 3: tôn trọng rotation +90° bằng FFmpeg autorotate, không xoay thêm.','- Video 14 và 16: tôn trọng rotation −180° bằng FFmpeg autorotate, không xoay thêm.','- Video dọc giữ trọn khung, đặt trên nền lấy từ chính video và làm mờ. Bảng tên xanh OPPO nằm ngoài vùng nội dung video, chữ trắng/chức vụ champagne, trượt lên và hiện 3,75 giây.','- Intro dùng toàn bộ nhạc `abydos_music-opening-epic-logo-193120.mp3`, nối qua tiêu đề ngắn.','- `public/music/NHẠC 20.10.mp3` được kiểm tra đúng tên Unicode; phát một lần liên tục theo con trỏ nguồn, tạm dừng/nối qua bốn nhóm ảnh bằng fade.','- Nhạc piano/ambient không lời do mã dự án tự tạo, không lấy bản thu bên ngoài. Nối chéo các vòng nhạc, tự hạ dưới tiếng nói; mỗi giọng được lọc nhẹ và chuẩn hóa khoảng −17 LUFS, true peak −3 dB. Cuối phim fade 3 giây.','','## Xuất trên máy tính','','Cần Node.js 22+, Python 3.12+, FFmpeg và font DejaVu (Linux: `sudo apt-get install ffmpeg fonts-dejavu-core`). Font có đầy đủ dấu tiếng Việt.','','```bash','npm ci','python3 -m pip install -r scripts/final/requirements.txt','npm run render:fast','npm run verify:render','```','','File xuất: `out/oppo-bac-ninh-20-10-final-short-1440p60.mp4`.','','Để xem trong Remotion Studio: chạy `npm run media:prepare`, `npm run media:stage`, rồi `npm run studio`. Composition `OppoBacNinh2010` sử dụng cùng 79 scene đã dựng và cùng bản phối âm thanh như đường xuất nhanh, nên giữ đúng hiệu ứng, chữ và hướng xoay. Lệnh `npm run render` xuất qua Remotion; `render:fast` xuất bằng FFmpeg để giảm thời gian trên Actions.','','## GitHub Actions','','Workflow **Render OPPO Final Short 1440p60** chạy kiểm kê, xem thử, render và kiểm tra. Chỉ tải artifact sau khi toàn bộ kiểm tra thành công: **OPPO-Bac-Ninh-20-10-Final-Short-1440p60**, lưu 14 ngày. Bên trong có MP4, preview, contact sheet, timeline, báo cáo cắt lời chúc, âm thanh và QA.','','Báo cáo `qa-report.json` kiểm tra số frame/thời lượng, H.264 1440p60, AAC stereo; đối chiếu khung hình thực tế của cả 52 ảnh và 16 video với scene nguồn; đối chiếu âm thanh AAC với bản phối; giải mã toàn bộ file để phát hiện lỗi mã hóa. Contact sheet dùng cho kiểm tra hình trực quan.']
(ROOT/'FINAL-SHORT.md').write_text('\n'.join(lines)+'\n')
